-- ========================================
-- novel-agent-platform: 数据库 schema
-- PostgreSQL 14+, 所有主键使用 GENERATED BY DEFAULT AS IDENTITY
-- ========================================

-- 模型配置 (多 LLM endpoint 管理)
CREATE TABLE IF NOT EXISTS t_model_config (
    id              BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name            VARCHAR(100) NOT NULL,
    base_url        VARCHAR(500) NOT NULL,
    api_key         VARCHAR(500) NOT NULL,
    model_name      VARCHAR(200) NOT NULL,
    temperature     DOUBLE PRECISION DEFAULT 0.7,
    timeout_seconds INT          NOT NULL DEFAULT 120,
    max_tokens      INT,
    active          BOOLEAN      NOT NULL DEFAULT FALSE,
    create_time     TIMESTAMP    NOT NULL DEFAULT now(),
    update_time     TIMESTAMP    NOT NULL DEFAULT now()
);

-- 角色-模型绑定 (每个 Agent 可独立选择模型配置)
CREATE TABLE IF NOT EXISTS t_model_role_binding (
    id              BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    agent_role      VARCHAR(64)  NOT NULL,          -- 角色标识, 如 world-builder / outline-architect / chapter-writer ...
    model_config_id BIGINT       NOT NULL,          -- 关联 t_model_config.id
    profile         VARCHAR(16)  NOT NULL DEFAULT 'balanced', -- creative / balanced / strict
    create_time     TIMESTAMP    NOT NULL DEFAULT now(),
    update_time     TIMESTAMP    NOT NULL DEFAULT now(),
    UNIQUE (agent_role)
);

-- 小说项目主表
CREATE TABLE IF NOT EXISTS t_novel_project (
    id              BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title           VARCHAR(200) NOT NULL,
    genre           VARCHAR(32)  NOT NULL,
    user_id         VARCHAR(64)  DEFAULT '',
    user_idea       TEXT,
    worldview       TEXT,
    characters      TEXT,
    outline         TEXT,
    writing_console TEXT,
    rolling_summary TEXT,
    status          VARCHAR(20)  NOT NULL DEFAULT 'DRAFT',
    stage           VARCHAR(40),
    total_chapters  INT          NOT NULL DEFAULT 0,
    current_chapter INT          NOT NULL DEFAULT 0,
    error_msg       TEXT,
    create_time     TIMESTAMP    NOT NULL DEFAULT now(),
    update_time     TIMESTAMP    NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_novel_project_user ON t_novel_project (user_id, create_time);

-- 小说章节
CREATE TABLE IF NOT EXISTS t_novel_chapter (
    id             BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id     BIGINT       NOT NULL,
    chapter_no     INT          NOT NULL,
    title          VARCHAR(300),
    outline        TEXT,
    content        TEXT,
    summary        TEXT,
    review_passed  BOOLEAN      DEFAULT TRUE,
    review_issues  TEXT,
    needs_review   BOOLEAN      DEFAULT FALSE,
    rewrite_rounds INT          NOT NULL DEFAULT 0,
    word_count     INT          NOT NULL DEFAULT 0,
    create_time    TIMESTAMP    NOT NULL DEFAULT now(),
    update_time    TIMESTAMP    NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_novel_chapter ON t_novel_chapter (project_id, chapter_no);

-- Agent 执行日志
CREATE TABLE IF NOT EXISTS t_novel_agent_log (
    id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id    BIGINT       NOT NULL,
    chapter_no    INT,
    agent_name    VARCHAR(64)  NOT NULL,
    stage         VARCHAR(40),
    input_summary VARCHAR(500),
    output_text   TEXT,
    elapsed_ms    INT          NOT NULL DEFAULT 0,
    create_time   TIMESTAMP    NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_novel_agent_log ON t_novel_agent_log (project_id, create_time);
